import type { Link } from '@unhead/vue';

type Theme = 'dark' | 'light';

/**
 * Theme-aware favicon links (generated by `npm run icons`). Rendered through
 * useHead in app.vue, so Unhead swaps the hrefs whenever the site theme changes.
 * favicon.ico and the apple-touch icon stay static in nuxt.config.ts.
 */
export function themeFaviconLinks(theme: Theme): Link[] {
	const variant = theme === 'light' ? '-light' : '';
	return [
		{ key: 'favicon-32', rel: 'icon', type: 'image/png', sizes: '32x32', href: `/icons/favicon${variant}-32x32.png` },
		{ key: 'favicon-16', rel: 'icon', type: 'image/png', sizes: '16x16', href: `/icons/favicon${variant}-16x16.png` },
		{ key: 'favicon-svg', rel: 'icon', type: 'image/svg+xml', href: `/favicon-${theme}.svg` },
	];
}
